The classical two-pointer algorithm with star backtracking:

```go
func matchParts(parts []atom, s []rune) bool {
    pi, si := 0, 0
    star := -1
    match := 0
    for si < len(s) {
        matched := false
        if pi < len(parts) {
            a := parts[pi]
            switch a.kind {
            case kindStar:
                star = pi
                match = si
                pi++
                matched = true
            case kindAny:
                pi++
                si++
                matched = true
            default:
                if atomMatches(a, s[si]) {
                    pi++; si++
                    matched = true
                }
            }
        }
        if matched {
            continue
        }
        if star >= 0 {
            // backtrack: extend the star's match by one rune
            pi = star + 1
            match++
            si = match
        } else {
            return false
        }
    }
    // consume trailing stars
    for pi < len(parts) && parts[pi].kind == kindStar {
        pi++
    }
    return pi == len(parts)
}
```

