```go
func tokenize(line string) ([]string, error) {
	var toks []string
	i := 0
	n := len(line)
	for i < n {
		// skip whitespace
		for i < n && (line[i] == ' ' || line[i] == '\t') {
			i++
		}
		if i >= n {
			break
		}
		if line[i] == '"' {
			i++
			var b strings.Builder
			terminated := false
			for i < n {
				c := line[i]
				if c == '\\' && i+1 < n {
					next := line[i+1]
					switch next {
					case '"', '\\', 'n':
						switch next {
						case 'n':
							b.WriteByte('\n')
						default:
							b.WriteByte(next)
						}
						i += 2
						continue
					}
					// unknown escape: write the backslash? or error? 
					b.WriteByte(c)
					i++
					continue
				}
				if c == '"' {
					i++
					terminated = true
					break
				}
				b.WriteByte(c)
				i++
			}
			if !terminated {
				return nil, errSyntax
			}
			toks = append(toks, b.String())
		} else {
			start := i
			for i < n && line[i] != ' ' && line[i] != '\t' {
				i++
			}
			toks = append(toks, line[start:i])
		}
	}
	return toks, nil
}
