	"example.com/kv/store"
)

const maxLine = 64 * 1024

func Serve(ctx context.Context, l net.Listener, s *store.Store) error {
	var conns sync.WaitGroup
	open := make(map[net.Conn]struct{})
	var mu sync.Mutex

	acceptDone := make(chan struct{})
	go func() {
		defer close(acceptDone)
		for {
			c, err := l.Accept()
			if err != nil {
				return
			}
			mu.Lock()
			open[c] = struct{}{}
			mu.Unlock()
			conns.Add(1)
			go func() {
				defer conns.Done()
				defer c.Close()
				defer func() {
					mu.Lock()
					delete(open, c)
					mu.Unlock()
				}()
				serveConn(c, s)
			}()
		}
	}()

	<-ctx.Done()
	l.Close()
	mu.Lock()
	for c := range open {
		c.Close()
	}
	mu.Unlock()
	conns.Wait()
	<-acceptDone
	return nil
}
```

Note: after l.Close(), Accept returns an error, and the accept goroutine terminates. After that, close all open connections, wait, and return nil.

serveConn:

```go
func serveConn(c net.Conn, s *store.Store) {
	r := bufio.NewReader(c)
	w := bufio.NewWriter(c)
	for {
		line, err := readLine(r)
		if err != nil {
			return
		}
		if len(line) > maxLine {
			io.WriteString(w, "-ERR line too long\n")
			w.Flush()
			return
		}
		line = strings.TrimSuffix(line, "\r")
		resp := proto.Exec(s, line)
		io.WriteString(w, resp)
		w.Flush()
		if isQuit(line) {
			return
		}
	}
}
```

readLine using ReadString('\n'): returns data containing a trailing \n, or an error (EOF) possibly accompanied by partial data. If EOF comes with partial data... the spec says lines are \n-terminated, so if the connection is closed, just terminate the connection.

```go
func readLine(r *bufio.Reader) (string, error) {
	for {
		line, err := r.ReadString('\n')
		if err == nil {
			return line, nil
		}
		if err == io.EOF {
			if line == "" {
				return "", io.EOF
			}
			// Partial line: if it exceeds the limit, treat it as too long
			return line, nil  // hmm
		}
		return "", err
	}
}
```

In practice, the loop is unnecessary. ReadString already accumulates across internal buffer reads. One call returns the complete line (up to \n) or an error. So:

```go
func readLine(r *bufio.Reader) (string, error) {
	line, err := r.ReadString('\n')
	if err == io.EOF {
		return line, io.EOF  // may be empty or partial
	}
	if err != nil {
		return "", err
	}
	return line, nil
}
```

Next, in serveConn: if err != nil → return (close). len(line) > maxLine → too-long error. Otherwise strip \r, execute, and write.

Wait, "lines exceeding 64 KiB" → -ERR line too long\n, close. maxLine = 64*1024; len(line) includes the trailing \n and possibly \r. That's fine — a line exceeding 64KiB.

isQuit: first token, case-insensitive "quit".

```go
func isQuit(line string) bool {
	line = strings.TrimSpace(line)
	i := 0
	for i < len(line) && (line[i] == ' ' || line[i] == '\t') {
		i++
	}
	for i < len(line) && line[i] != ' ' && line[i] != '\t' {
		i++
	}
	return strings.EqualFold(line[:i], "quit")
}
```

More simply: strings.FieldsFunc. Or: first := strings.Fields(line)[0] after TrimSpace... Fields splits on all whitespace. That's fine:

```go
func isQuit(line string) bool {
	fields := strings.Fields(line)
	return len(fields) > 0 && strings.EqualFold(fields[0], "quit")
}
```

Hmm, but what about a quoted "QUIT"? Edge case, so ignore it.

Actually — the spec says "the QUIT command returns +BYE\n and closes that connection." proto.Exec also handles QUIT → +BYE. So if the server passes QUIT to Exec, it gets +BYE, and then the server checks whether the line is QUIT and closes. This works: the response is written by Exec, and then the connection is closed.

